CREATE TABLE rol (
    codrol BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomrol VARCHAR(50) NOT NULL UNIQUE,
    desrol VARCHAR(200),
    estrol BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE usuario (
    codusu BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    uuidusu UUID NOT NULL UNIQUE,
    codrol BIGINT NOT NULL,
    nomusu VARCHAR(100) NOT NULL,
    apepatusu VARCHAR(100) NOT NULL,
    apematusu VARCHAR(100),
    corusu VARCHAR(254) NOT NULL UNIQUE,
    estusu BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_usuario_rol FOREIGN KEY (codrol) REFERENCES rol(codrol),
    CONSTRAINT fk_usuario_auth FOREIGN KEY (uuidusu) REFERENCES auth.users(id)
);

CREATE TABLE tipomotocar (
    codtmo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomtmo VARCHAR(100) NOT NULL UNIQUE,
    destmo VARCHAR(250),
    esttmo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE modelo (
    codmod BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codtmo BIGINT NOT NULL,
    nommod VARCHAR(100) NOT NULL,
    marmod VARCHAR(100) NOT NULL DEFAULT 'Bajaj',
    desmod TEXT NOT NULL,
    carmod TEXT NOT NULL,
    estmod VARCHAR(20) NOT NULL DEFAULT 'Borrador',
    CONSTRAINT fk_modelo_tipomotocar FOREIGN KEY (codtmo) REFERENCES tipomotocar(codtmo),
    CONSTRAINT chk_modelo_estado CHECK (estmod IN ('Borrador', 'Publicado', 'No publicado'))
);

CREATE TABLE imagenmodelo (
    codimo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codmod BIGINT NOT NULL,
    urlimo TEXT NOT NULL,
    ordimo INTEGER NOT NULL DEFAULT 1,
    estimo BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_imagenmodelo_modelo FOREIGN KEY (codmod) REFERENCES modelo(codmod),
    CONSTRAINT chk_imagenmodelo_orden CHECK (ordimo > 0)
);

CREATE TABLE proveedor (
    codpro BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nompro VARCHAR(120) NOT NULL UNIQUE,
    dirpro VARCHAR(250),
    telpro VARCHAR(20),
    corpro VARCHAR(254),
    estpro BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE tipotecho (
    codtte BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomtte VARCHAR(100) NOT NULL UNIQUE,
    destte VARCHAR(250),
    reqprotte BOOLEAN NOT NULL DEFAULT FALSE,
    esttte BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE estadopreparacion (
    codepr BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomepr VARCHAR(100) NOT NULL UNIQUE,
    desepr VARCHAR(250),
    actepr BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE ubicacion (
    codubi BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomubi VARCHAR(120) NOT NULL UNIQUE,
    tipubi VARCHAR(30) NOT NULL,
    dirubi VARCHAR(250),
    estubi BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT chk_ubicacion_tipo CHECK (tipubi IN ('Sede', 'Almacen', 'Proveedor'))
);

CREATE TABLE sede (
    codsed BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codubi BIGINT NOT NULL UNIQUE,
    telsed VARCHAR(20),
    horsed VARCHAR(150),
    estsed BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_sede_ubicacion FOREIGN KEY (codubi) REFERENCES ubicacion(codubi)
);

CREATE TABLE compra (
    codcom BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codmod BIGINT NOT NULL,
    codusu BIGINT NOT NULL,
    colcom VARCHAR(50) NOT NULL,
    feccom DATE NOT NULL DEFAULT CURRENT_DATE,
    horcom TIME NOT NULL DEFAULT CURRENT_TIME,
    cancom INTEGER NOT NULL,
    estcom VARCHAR(30) NOT NULL DEFAULT 'Pendiente de factura',
    obscom TEXT,
    CONSTRAINT fk_compra_modelo FOREIGN KEY (codmod) REFERENCES modelo(codmod),
    CONSTRAINT fk_compra_usuario FOREIGN KEY (codusu) REFERENCES usuario(codusu),
    CONSTRAINT chk_compra_cantidad CHECK (cancom > 0),
    CONSTRAINT chk_compra_estado CHECK (estcom IN ('Pendiente de factura', 'Identificada'))
);

CREATE TABLE unidad (
    coduni BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codcom BIGINT NOT NULL,
    codmod BIGINT NOT NULL,
    codubi BIGINT,
    codtte BIGINT,
    codpro BIGINT,
    codepr BIGINT,
    nummotuni VARCHAR(100) NOT NULL UNIQUE,
    chauni VARCHAR(100) NOT NULL UNIQUE,
    coluni VARCHAR(50),
    dettecuni TEXT,
    estcomuni VARCHAR(50) NOT NULL DEFAULT 'No disponible',
    fecreguni TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    obsuni TEXT,
    CONSTRAINT fk_unidad_compra FOREIGN KEY (codcom) REFERENCES compra(codcom),
    CONSTRAINT fk_unidad_modelo FOREIGN KEY (codmod) REFERENCES modelo(codmod),
    CONSTRAINT fk_unidad_ubicacion FOREIGN KEY (codubi) REFERENCES ubicacion(codubi),
    CONSTRAINT fk_unidad_tipotecho FOREIGN KEY (codtte) REFERENCES tipotecho(codtte),
    CONSTRAINT fk_unidad_proveedor FOREIGN KEY (codpro) REFERENCES proveedor(codpro),
    CONSTRAINT fk_unidad_estadopreparacion FOREIGN KEY (codepr) REFERENCES estadopreparacion(codepr)
);

CREATE TABLE movimientoubicacion (
    codmub BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    coduni BIGINT NOT NULL,
    codubiori BIGINT NOT NULL,
    codubides BIGINT NOT NULL,
    codusu BIGINT NOT NULL,
    fecmub DATE NOT NULL DEFAULT CURRENT_DATE,
    hormub TIME NOT NULL DEFAULT CURRENT_TIME,
    obsmub TEXT,
    CONSTRAINT fk_movubicacion_unidad FOREIGN KEY (coduni) REFERENCES unidad(coduni),
    CONSTRAINT fk_movubicacion_origen FOREIGN KEY (codubiori) REFERENCES ubicacion(codubi),
    CONSTRAINT fk_movubicacion_destino FOREIGN KEY (codubides) REFERENCES ubicacion(codubi),
    CONSTRAINT fk_movubicacion_usuario FOREIGN KEY (codusu) REFERENCES usuario(codusu),
    CONSTRAINT chk_movubicacion_distinta CHECK (codubiori <> codubides)
);

CREATE TABLE tipodocumento (
    codtdo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomtdo VARCHAR(50) NOT NULL UNIQUE,
    esttdo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE cliente (
    codcli BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codtdo BIGINT NOT NULL,
    numdoccli VARCHAR(20) NOT NULL UNIQUE,
    nomcli VARCHAR(100) NOT NULL,
    apepatcli VARCHAR(100),
    apematcli VARCHAR(100),
    telcli VARCHAR(20),
    corcli VARCHAR(254),
    dircli VARCHAR(250),
    estcli BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_cliente_tipodocumento FOREIGN KEY (codtdo) REFERENCES tipodocumento(codtdo)
);

CREATE TABLE separacion (
    codsep BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    coduni BIGINT NOT NULL,
    codcli BIGINT NOT NULL,
    codusu BIGINT NOT NULL,
    metpagsep VARCHAR(50) NOT NULL,
    monadesep NUMERIC(10,2) NOT NULL,
    refsep VARCHAR(200),
    fecsep TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    feccansep TIMESTAMPTZ,
    motcansep VARCHAR(250),
    obssep TEXT,
    estsep VARCHAR(30) NOT NULL DEFAULT 'Activa',
    CONSTRAINT fk_separacion_unidad FOREIGN KEY (coduni) REFERENCES unidad(coduni),
    CONSTRAINT fk_separacion_cliente FOREIGN KEY (codcli) REFERENCES cliente(codcli),
    CONSTRAINT fk_separacion_usuario FOREIGN KEY (codusu) REFERENCES usuario(codusu),
    CONSTRAINT chk_separacion_monto CHECK (monadesep > 0)
);

CREATE TABLE venta (
    codven BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    coduni BIGINT NOT NULL,
    codcli BIGINT NOT NULL,
    codusu BIGINT NOT NULL,
    fecven TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    modcomven VARCHAR(50) NOT NULL,
    obsven TEXT,
    estven VARCHAR(30) NOT NULL DEFAULT 'Registrada',
    CONSTRAINT fk_venta_unidad FOREIGN KEY (coduni) REFERENCES unidad(coduni),
    CONSTRAINT fk_venta_cliente FOREIGN KEY (codcli) REFERENCES cliente(codcli),
    CONSTRAINT fk_venta_usuario FOREIGN KEY (codusu) REFERENCES usuario(codusu)
);

CREATE TABLE canalwhatsapp (
    codcwa BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nomcwa VARCHAR(100) NOT NULL,
    numcwa VARCHAR(20) NOT NULL UNIQUE,
    enlcwa TEXT NOT NULL,
    estcwa BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE lead (
    codlea BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codmod BIGINT,
    codusu BIGINT,
    codcwa BIGINT,
    nomlea VARCHAR(150) NOT NULL,
    tellea VARCHAR(20),
    orilea VARCHAR(30) NOT NULL,
    canlea VARCHAR(50) NOT NULL,
    fecreglea TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    obslea TEXT,
    estlea VARCHAR(50) NOT NULL DEFAULT 'Nuevo',
    CONSTRAINT fk_lead_modelo FOREIGN KEY (codmod) REFERENCES modelo(codmod),
    CONSTRAINT fk_lead_usuario FOREIGN KEY (codusu) REFERENCES usuario(codusu),
    CONSTRAINT fk_lead_canalwhatsapp FOREIGN KEY (codcwa) REFERENCES canalwhatsapp(codcwa)
);

CREATE TABLE seguimientolead (
    codsle BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codlea BIGINT NOT NULL,
    codusu BIGINT NOT NULL,
    fecinisle TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    horsle TIME,
    tipsle VARCHAR(50),
    dessle TEXT,
    fecprosle TIMESTAMPTZ,
    CONSTRAINT fk_seguimientolead_lead FOREIGN KEY (codlea) REFERENCES lead(codlea),
    CONSTRAINT fk_seguimientolead_usuario FOREIGN KEY (codusu) REFERENCES usuario(codusu)
);
